 m=json.loads(p.read_text()); actual=hashlib.sha256((p.parent/"queries.jsonl").read_bytes()).hexdigest(); recorded=m.get("sha256"); print(p.parent.name, "sha_ok" if recorded==actual else "SHA_MISMATCH" if recorded else "no_sha")'

