def test_rejects_registry_entries_for_an_omitted_requested_source(tmp_path):
    pool = builder_pool(tmp_path, {"swe_smith": 6, "swe_rebench": 4})
    registry = tmp_path / "registry.json"
    registry.write_text(json.dumps({"selected": [
        {"source": "r2e_gym", "instance_id": "excluded-elsewhere"}
    ]}) + "\n", encoding="utf-8")
    assert run_gate(
        pool, registry, POOL_EXPECTED_SOURCE_COUNTS="swe_smith=6,swe_rebench=4,r2e_gym=0"
    ).returncode != 0
    # A legacy zero-weight omission is valid when the case does not request that source.
    assert run_gate(pool, registry).returncode == 0

